package qdrant;

// Service for reading raw files from a collection's on-disk storage.
//
// All requests are subject to collection-level access control and path
// validation. Paths are always interpreted relative to the collection's
// storage directory.
service StorageRead {
  // Check whether a file exists at the given path within a collection.
  rpc FileExists(FileExistsRequest) returns (FileExistsResponse) {}
  // List files within a collection whose relative path starts with a prefix.
  rpc ListFiles(ListFilesRequest) returns (ListFilesResponse) {}
  // Get the byte length of a file.
  rpc FileLength(FileLengthRequest) returns (FileLengthResponse) {}
  // Read a byte range from a file.
  rpc ReadBytes(ReadBytesRequest) returns (ReadBytesResponse) {}
  // Read a byte range from a file, streamed in chunks.
  rpc ReadBytesStream(ReadBytesStreamRequest) returns (stream ReadBytesStreamResponse) {}
  // Read the entire contents of a file.
  rpc ReadWhole(ReadWholeRequest) returns (ReadWholeResponse) {}
  // Read multiple byte ranges from a single file.
  rpc ReadBatch(ReadBatchRequest) returns (ReadBatchResponse) {}
  // Read byte ranges from multiple files.
  rpc ReadMulti(ReadMultiRequest) returns (ReadMultiResponse) {}
}

message FileExistsRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
}

message FileExistsResponse {
  bool exists = 1; // Whether the file exists
}

message ListFilesRequest {
  string collection_name = 1; // Name of the collection
  string prefix_path = 2; // Only return files whose relative path starts with this prefix
}

message ListFilesResponse {
  repeated string paths = 1; // Paths relative to the collection directory
}

message FileLengthRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
}

message FileLengthResponse {
  uint64 length = 1; // Length of the file in bytes
}

message ReadBytesRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
  uint64 byte_offset = 3; // Offset in bytes at which to start reading
  uint64 length = 4; // Number of bytes to read
}

message ReadBytesResponse {
  bytes data = 1; // The requested bytes
}

message ReadBytesStreamRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
  uint64 byte_offset = 3; // Offset in bytes at which to start reading
  uint64 length = 4; // Number of bytes to read
}

message ReadBytesStreamResponse {
  bytes data = 1; // A chunk of the requested bytes
}

message ReadWholeRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
}

message ReadWholeResponse {
  bytes data = 1; // The full file contents
}

message ReadBatchRange {
  uint64 byte_offset = 1; // Offset in bytes at which to start reading
  uint64 length = 2; // Number of bytes to read
}

message ReadBatchRequest {
  string collection_name = 1; // Name of the collection
  string path = 2; // Path to the file, relative to the collection directory
  repeated ReadBatchRange ranges = 3; // Byte ranges to read from the file
}

message ReadBatchResponse {
  repeated bytes data = 1; // One byte slice per requested range, in request order
}

message ReadMultiEntry {
  string path = 1; // Path to the file, relative to the collection directory
  uint64 byte_offset = 2; // Offset in bytes at which to start reading
  uint64 length = 3; // Number of bytes to read
}

message ReadMultiRequest {
  string collection_name = 1; // Name of the collection
  repeated ReadMultiEntry reads = 2; // Reads to perform, potentially from different files
}

message ReadMultiResponse {
  repeated bytes data = 1; // One byte slice per read, in request order
}
