/// Maximum number of bytes carried by a single [`ReadBytesStreamResponse`]
/// chunk. Reads larger than this value are split so that every chunk but the
/// last carries exactly `STREAM_CHUNK_SIZE` bytes.
const STREAM_CHUNK_SIZE: u64 = 2 * 1024 * 1024;

/// Abstraction over an on-disk file that can be opened and read by offset.
///
/// This is parameterized so the service can be exercised against different file
/// backends; the production implementation is [`MmapFile`].
pub trait StorageFile: Sized {
    /// Open the file at the given path.
    fn open(path: &Path) -> io::Result<Self>;

    /// Total length of the file in bytes.
    fn len(&self) -> u64;

    /// Read `length` bytes starting at `offset`.
    ///
    /// Returns [`Status`] with [`tonic::Code::OutOfRange`] when the requested
    /// range extends beyond the end of the file.
    fn read_range(&self, offset: u64, length: u64) -> Result<Vec<u8>, Status>;
}

/// Memory-mapped implementation of [`StorageFile`].
pub struct MmapFile {
    /// The memory map, or `None` for empty files (which cannot be mmap'd).
    mmap: Option<memmap2::Mmap>,
    /// Cached file length in bytes.
    len: u64,
}

impl StorageFile for MmapFile {
    fn open(path: &Path) -> io::Result<Self> {
        let file = std::fs::File::open(path)?;
        let len = file.metadata()?.len();
        // Memory mapping an empty file is not supported by the OS, so we simply
        // represent it as an empty map.
        let mmap = if len == 0 {
            None
        } else {
            // SAFETY: the file is opened read-only and the map is owned by this
            // struct for its whole lifetime.
            Some(unsafe { memmap2::Mmap::map(&file)? })
        };
        Ok(Self { mmap, len })
    }

    fn len(&self) -> u64 {
        self.len
    }

    fn read_range(&self, offset: u64, length: u64) -> Result<Vec<u8>, Status> {
        let end = offset
            .checked_add(length)
            .filter(|end| *end <= self.len)
            .ok_or_else(|| {
                Status::out_of_range(format!(
                    "Requested range [{offset}, {}) exceeds file length {}",
                    offset.saturating_add(length),
                    self.len,
                ))
            })?;

        let bytes = self.mmap.as_deref().unwrap_or(&[]);
        Ok(bytes[offset as usize..end as usize].to_vec())
    }
}

