use super::*;
use crate::common::helpers::{
    create_general_purpose_runtime, create_search_runtime, create_update_runtime,
};

fn make_dispatcher(storage_path: &std::path::Path) -> Arc<Dispatcher> {
    let mut settings = crate::Settings::new(None).expect("Can't read config.");
    settings.storage.storage_path = storage_path.to_path_buf();
    let search_runtime = create_search_runtime(2).unwrap();
    let update_runtime = create_update_runtime(2).unwrap();
    let general_runtime = create_general_purpose_runtime().unwrap();
    let toc = TableOfContent::new(
        &settings.storage,
        search_runtime,
        update_runtime,
        general_runtime,
        ResourceBudget::default(),
        ChannelService::new(settings.service.http_port, settings.service.enable_tls, None, None),
        0,
        None,
    );
    Arc::new(Dispatcher::new(Arc::new(toc)))
}

fn service_with_files(files: &[(&str, &[u8])]) -> (StorageReadService<MmapFile>, tempfile::TempDir) {
    let storage_dir = Builder::new().prefix("storage").tempdir().unwrap();
    let dispatcher = make_dispatcher(storage_dir.path());
    let collection_dir = storage_dir.path().join("collections").join("my_collection");
    std::fs::create_dir_all(&collection_dir).unwrap();
    for (rel, contents) in files {
        let path = collection_dir.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        std::fs::write(path, contents).unwrap();
    }
    (StorageReadService::new(dispatcher), storage_dir)
}

fn scoped_auth(collection: &str) -> Auth {
    Auth::new(
        Access::Collection(CollectionAccessList(vec![CollectionAccess {
            collection: collection.to_string(),
            access: CollectionAccessMode::Read,
            payload: None,
        }])),
        None,
        None,
        AuthType::None,
        None,
    )
}

fn req<T>(inner: T) -> Request<T> {
    Request::new(inner)
}

#[tokio::test]
async fn test_file_exists() {
    let (svc, _d) = service_with_files(&[("data.bin", b"hello")]);
    let resp = svc
        .file_exists(req(FileExistsRequest {
            collection_name: "my_collection".into(),
            path: "data.bin".into(),
        }))
        .await
        .unwrap();
    assert!(resp.into_inner().exists);

    let resp = svc
        .file_exists(req(FileExistsRequest {
            collection_name: "my_collection".into(),
            path: "missing.bin".into(),
        }))
        .await
        .unwrap();
    assert!(!resp.into_inner().exists);
}

