use std::sync::Arc;

use collection::shards::channel_service::ChannelService;
use common::budget::ResourceBudget;
use futures::StreamExt;
use storage::content_manager::toc::TableOfContent;
use storage::dispatcher::Dispatcher;
use storage::rbac::{
    Access, Auth, AuthType, CollectionAccess, CollectionAccessList, CollectionAccessMode,
};
use tempfile::Builder;
use tonic::Code;

use super::*;
use crate::common::helpers::{
    create_general_purpose_runtime, create_search_runtime, create_update_runtime,
};

/// Build a dispatcher on a dedicated thread so runtime construction does not
/// happen inside the async test runtime.
fn make_dispatcher(storage_path: &Path) -> Arc<Dispatcher> {
    let storage_path = storage_path.to_path_buf();
    std::thread::spawn(move || {
        let mut settings = crate::Settings::new(None).expect("Can't read config.");
        settings.storage.storage_path = storage_path;
        let search_runtime = create_search_runtime(2).unwrap();
        let update_runtime = create_update_runtime(2).unwrap();
        let general_runtime = create_general_purpose_runtime().unwrap();
        let toc = TableOfContent::new(
            &settings.storage,
            search_runtime,
            update_runtime,
            general_runtime,
            ResourceBudget::default(),
            ChannelService::new(
                settings.service.http_port,
                settings.service.enable_tls,
                None,
                None,
            ),
            0,
            None,
        );
        Arc::new(Dispatcher::new(Arc::new(toc)))
    })
    .join()
    .unwrap()
}

fn service_with_files(
    files: &[(&str, &[u8])],
) -> (StorageReadService<MmapFile>, tempfile::TempDir) {
    let storage_dir = Builder::new().prefix("storage").tempdir().unwrap();
    let dispatcher = make_dispatcher(storage_dir.path());
    let collection_dir = storage_dir.path().join("collections").join("my_collection");
    std::fs::create_dir_all(&collection_dir).unwrap();
    for (rel, contents) in files {
        let path = collection_dir.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        std::fs::write(path, contents).unwrap();
    }
    (StorageReadService::new(dispatcher), storage_dir)
}

fn scoped_auth(collection: &str) -> Auth {
    Auth::new(
        Access::Collection(CollectionAccessList(vec![CollectionAccess {
            collection: collection.to_string(),
            access: CollectionAccessMode::Read,
            payload: None,
        }])),
        None,
        None,
        AuthType::None,
        None,
    )
}

fn req<T>(inner: T) -> Request<T> {
    Request::new(inner)
}

#[tokio::test]
async fn test_file_exists() {
    let (svc, _d) = service_with_files(&[("data.bin", b"hello")]);
    let resp = svc
        .file_exists(req(FileExistsRequest {
            collection_name: "my_collection".into(),
            path: "data.bin".into(),
        }))
        .await
        .unwrap();
    assert!(resp.into_inner().exists);

    let resp = svc
        .file_exists(req(FileExistsRequest {
            collection_name: "my_collection".into(),
            path: "missing.bin".into(),
        }))
        .await
        .unwrap();
    assert!(!resp.into_inner().exists);
}

#[tokio::test]
async fn test_list_files_prefix() {
    let (svc, _d) = service_with_files(&[
        ("segments/a.bin", b"a"),
        ("segments/b.bin", b"b"),
        ("wal/c.bin", b"c"),
    ]);
    let resp = svc
        .list_files(req(ListFilesRequest {
            collection_name: "my_collection".into(),
            prefix_path: "segments".into(),
        }))
        .await
        .unwrap()
        .into_inner();
    let mut paths = resp.paths;
    paths.sort();
    assert_eq!(paths, vec!["segments/a.bin", "segments/b.bin"]);
}

#[tokio::test]
async fn test_file_length_and_notfound() {
    let (svc, _d) = service_with_files(&[("data.bin", b"hello")]);
    let resp = svc
        .file_length(req(FileLengthRequest {
            collection_name: "my_collection".into(),
            path: "data.bin".into(),
        }))
        .await
        .unwrap();
    assert_eq!(resp.into_inner().length, 5);

    let err = svc
        .file_length(req(FileLengthRequest {
            collection_name: "my_collection".into(),
            path: "missing.bin".into(),
        }))
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::NotFound);

    let err = svc
        .file_length(req(FileLengthRequest {
            collection_name: "no_such_collection".into(),
            path: "data.bin".into(),
        }))
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::NotFound);
}

#[tokio::test]
async fn test_read_bytes_out_of_range() {
    let (svc, _d) = service_with_files(&[("data.bin", b"hello world")]);
    let resp = svc
        .read_bytes(req(ReadBytesRequest {
            collection_name: "my_collection".into(),
            path: "data.bin".into(),
            byte_offset: 6,
            length: 5,
        }))
        .await
        .unwrap();
    assert_eq!(resp.into_inner().data, b"world");

    let err = svc
        .read_bytes(req(ReadBytesRequest {
            collection_name: "my_collection".into(),
            path: "data.bin".into(),
            byte_offset: 6,
            length: 100,
        }))
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::OutOfRange);
}

#[tokio::test]
async fn test_read_bytes_stream_chunks() {
    let size = (STREAM_CHUNK_SIZE + 100) as usize;
    let contents = vec![7u8; size];
    let (svc, _d) = service_with_files(&[("big.bin", &contents)]);

    let stream = svc
        .read_bytes_stream(req(ReadBytesStreamRequest {
            collection_name: "my_collection".into(),
            path: "big.bin".into(),
            byte_offset: 0,
            length: size as u64,
        }))
        .await
        .unwrap()
        .into_inner();
    let chunks: Vec<_> = stream.collect::<Vec<_>>().await;
    assert_eq!(chunks.len(), 2);
    assert_eq!(chunks[0].as_ref().unwrap().data.len() as u64, STREAM_CHUNK_SIZE);
    assert_eq!(chunks[1].as_ref().unwrap().data.len(), 100);

    // Empty on length 0, existing file.
    let stream = svc
        .read_bytes_stream(req(ReadBytesStreamRequest {
            collection_name: "my_collection".into(),
            path: "big.bin".into(),
            byte_offset: 0,
            length: 0,
        }))
        .await
        .unwrap()
        .into_inner();
    let chunks: Vec<_> = stream.collect::<Vec<_>>().await;
    assert_eq!(chunks.len(), 0);

    // NotFound on length 0, missing file.
    let result = svc
        .read_bytes_stream(req(ReadBytesStreamRequest {
            collection_name: "my_collection".into(),
            path: "missing.bin".into(),
            byte_offset: 0,
            length: 0,
        }))
        .await;
    assert_eq!(result.err().unwrap().code(), Code::NotFound);

    // OutOfRange on too-large length.
    let result = svc
        .read_bytes_stream(req(ReadBytesStreamRequest {
            collection_name: "my_collection".into(),
            path: "big.bin".into(),
            byte_offset: 0,
            length: size as u64 + 1,
        }))
        .await;
    assert_eq!(result.err().unwrap().code(), Code::OutOfRange);
}

